css:
.d-tree-keyboard-navigation{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-tree-keyboard-navigation *,.d-tree-keyboard-navigation *::before,.d-tree-keyboard-navigation *::after{box-sizing:border-box}
.d-tree-keyboard-navigation [hidden]{display:none!important}
.d-tree-keyboard-navigation .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-tree-keyboard-navigation .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-tree-keyboard-navigation label{display:block;margin:8px 0}
.d-tree-keyboard-navigation input,.d-tree-keyboard-navigation select,.d-tree-keyboard-navigation textarea,.d-tree-keyboard-navigation button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-tree-keyboard-navigation input:not([type=checkbox]):not([type=radio]),.d-tree-keyboard-navigation select,.d-tree-keyboard-navigation textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-tree-keyboard-navigation button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-tree-keyboard-navigation button:disabled{opacity:.5;cursor:default}
.d-tree-keyboard-navigation :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-tree-keyboard-navigation [aria-invalid=true]{border-color:var(--warn)!important}
.d-tree-keyboard-navigation .d-scroll{max-width:100%;overflow:auto}
.d-tree-keyboard-navigation table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-tree-keyboard-navigation th,.d-tree-keyboard-navigation td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-tree-keyboard-navigation caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-tree-keyboard-navigation progress{width:100%;accent-color:var(--ink)}
.d-tree-keyboard-navigation pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-tree-keyboard-navigation h3,.d-tree-keyboard-navigation p{margin:8px 0}
.d-tree-keyboard-navigation [aria-pressed=true],.d-tree-keyboard-navigation [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-tree-keyboard-navigation .d-grow{flex:1;min-width:100px}
.d-tree-keyboard-navigation summary{cursor:pointer;padding:6px 0}
.d-tree-keyboard-navigation ul,.d-tree-keyboard-navigation ol{padding-left:24px}
.d-tree-keyboard-navigation [role=tree],.d-tree-keyboard-navigation [role=group]{list-style:none;padding-left:16px}.d-tree-keyboard-navigation [role=treeitem]{display:block;margin:4px 0}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{const items=qa('[role=treeitem]');const group=button=>button.parentElement.querySelector(':scope > [role=group]');const focus=button=>{items.forEach(item=>item.tabIndex=item===button?0:-1);button.focus();say(button.textContent);};items.forEach(button=>{button.tabIndex=-1;button.onclick=()=>{const child=group(button);if(child){child.hidden=!child.hidden;button.setAttribute('aria-expanded',String(!child.hidden));}focus(button);};button.onkeydown=event=>{const visible=items.filter(item=>!item.closest('[hidden]')),index=visible.indexOf(button),child=group(button);let target;if(event.key==='ArrowDown')target=visible[Math.min(index+1,visible.length-1)];else if(event.key==='ArrowUp')target=visible[Math.max(0,index-1)];else if(event.key==='Home')target=visible[0];else if(event.key==='End')target=visible.at(-1);else if(event.key==='ArrowRight'&&child){if(child.hidden){child.hidden=false;button.setAttribute('aria-expanded','true');}else target=child.querySelector('[role=treeitem]');}else if(event.key==='ArrowLeft'){if(child&&!child.hidden){child.hidden=true;button.setAttribute('aria-expanded','false');}else target=button.parentElement.parentElement.closest('li')?.querySelector(':scope > [role=treeitem]');}else return;event.preventDefault();if(target)focus(target);};});items[0].tabIndex=0;})(root, q, qa, say);
}
